export const paymentSlips = pgTable("payment_slips", {
	// You can use { mode: "bigint" } if numbers are exceeding js number limitations
	paymentId: bigint("payment_id", { mode: "number" }).primaryKey().generatedAlwaysAsIdentity({ name: "payment_slips_payment_id_seq", startWith: 1, increment: 1, minValue: 1, maxValue: 9223372036854775807, cache: 1 }),
	clubId: integer("club_id").notNull(),
	value: numeric({ precision: 12, scale:  2 }).notNull(),
	slipNumber: text("slip_number"),
	objectKey: text("object_key").notNull(),
	submittedBy: integer("submitted_by"),
	approved: boolean(),
	decidedBy: integer("decided_by"),
	decidedAt: timestamp("decided_at", { withTimezone: true, mode: 'string' }),
	createdAt: timestamp("created_at", { withTimezone: true, mode: 'string' }).defaultNow().notNull(),
}, (table) => [
	index("idx_slips_club").using("btree", table.clubId.asc().nullsLast().op("int4_ops"), table.approved.asc().nullsLast().op("int4_ops")),
	index("idx_slips_status").using("btree", table.approved.asc().nullsLast().op("bool_ops"), table.createdAt.desc().nullsFirst().op("bool_ops")),
	foreignKey({
			columns: [table.clubId],
			foreignColumns: [clubs.clubId],
			name: "payment_slips_club_id_fkey"
		}),
	check("payment_slips_value_check", sql`value > (0)::numeric`),
	check("payment_slips_check", sql`(approved IS NULL) = (decided_at IS NULL)`),
]);

